// Matchup difficulty for the Start/Sit optimizer (backlog item 1, remainder
// (a)): given a player's NFL team, position, and the league's current week,
// look up the week's opponent from the bundled schedule and the opponent's
// fantasy points allowed vs that position from completed weeks. Data is
// generated by `npm run fetch:matchups` (ESPN schedule + Sleeper weekly
// stats, all free); a season rollover only changes the generated JSON.
//
// Rank 1 = allows the most points to the position (easiest matchup).

import scheduleJson from '@/data/nflSchedule.2026.json';
import allowedJson from '@/data/matchupAllowed.2026.json';

export type MatchupLabel = 'favorable' | 'neutral' | 'tough';

export interface MatchupRating {
  /** Opponent's canonical abbreviation (JAC/WAS style). */
  opponent: string;
  /** Fantasy points per game the opponent allowed to the position. */
  avgAllowed: number;
  /** 1 = allows the most points (easiest), 32 = allows the fewest. */
  rank: number;
  label: MatchupLabel;
}

export interface ScheduleFile {
  season: number;
  weeks: Record<string, Array<[string, string]>>;
  generatedAt: string;
}

export interface AllowedFile {
  season: number;
  /** First and last completed week that fed the averages. */
  weeks: [number, number];
  teams: Record<string, Record<string, { avg: number; rank: number }>>;
  generatedAt: string;
}

// JSON imports widen tuples to arrays; assert through unknown so the
// tuple types in ScheduleFile/AllowedFile hold.
const SCHEDULE = scheduleJson as unknown as ScheduleFile;
const ALLOWED = allowedJson as unknown as AllowedFile;

const SKILL_POSITIONS = new Set(['QB', 'RB', 'WR', 'TE']);

function normalizePosition(pos: string | null | undefined): string | null {
  const upper = (pos ?? '').toUpperCase().trim();
  return SKILL_POSITIONS.has(upper) ? upper : null;
}

function labelFor(rank: number): MatchupLabel {
  if (rank <= 10) return 'favorable';
  if (rank >= 23) return 'tough';
  return 'neutral';
}

export function getMatchupRating(
  team: string | null | undefined,
  position: string | null | undefined,
  week: number | undefined,
  schedule: ScheduleFile = SCHEDULE,
  allowed: AllowedFile = ALLOWED,
): MatchupRating | null {
  const pos = normalizePosition(position);
  if (!team || week === undefined || pos === null) return null;
  const games = schedule.weeks[String(week)];
  const game = games?.find(([h, a]) => h === team || a === team);
  if (!game) return null;
  const opponent = game[0] === team ? game[1] : game[0];
  const entry = allowed.teams[opponent]?.[pos];
  if (!entry) return null;
  return {
    opponent,
    avgAllowed: entry.avg,
    rank: entry.rank,
    label: labelFor(entry.rank),
  };
}

/** Ordinal with "most" context: rank 1 → "most", rank 5 → "5th-most". */
export function rankPhrase(rank: number): string {
  if (rank === 1) return 'the most';
  const suffix =
    rank % 10 === 1 && rank % 100 !== 11
      ? 'st'
      : rank % 10 === 2 && rank % 100 !== 12
        ? 'nd'
        : rank % 10 === 3 && rank % 100 !== 13
          ? 'rd'
          : 'th';
  return `${rank}${suffix}-most`;
}

/** Full accessible label, e.g. "vs DAL · Favorable — DAL allows 23.4 pts/game to RBs (5th-most)". */
export function matchupLabel(rating: MatchupRating, position: string): string {
  const verdict =
    rating.label === 'favorable'
      ? 'Favorable'
      : rating.label === 'tough'
        ? 'Tough'
        : 'Neutral';
  return (
    `vs ${rating.opponent} · ${verdict} — ${rating.opponent} allows ` +
    `${rating.avgAllowed} pts/game to ${position.toUpperCase()}s (${rankPhrase(rating.rank)} points)`
  );
}

/** Compact table-cell text: "vs DAL · Favorable". */
export function matchupShort(rating: MatchupRating): string {
  const verdict =
    rating.label === 'favorable'
      ? 'Favorable'
      : rating.label === 'tough'
        ? 'Tough'
        : 'Neutral';
  return `vs ${rating.opponent} · ${verdict}`;
}

/** The completed-weeks range behind the bundled allowed averages, for the page footnote. */
export function matchupDataWeeks(): [number, number] {
  return ALLOWED.weeks;
}

/**
 * Best guess at the current NFL week when no league is loaded: the week
 * after the last completed week that fed the allowed averages, clamped into
 * the bundled schedule's range. Lets manual-mode pages (trade analyzer,
 * shared links) show matchup chips without a league's currentWeek.
 */
export function currentWeekEstimate(): number {
  const [, lastCompleted] = ALLOWED.weeks;
  const scheduleWeeks = Object.keys(SCHEDULE.weeks)
    .map(Number)
    .filter(n => Number.isFinite(n));
  const maxWeek = scheduleWeeks.length > 0 ? Math.max(...scheduleWeeks) : 18;
  return Math.min(Math.max(lastCompleted + 1, 1), maxWeek);
}

/**
 * League-wide average fantasy points per game allowed to a skill position
 * (mean of the per-team averages), the reference point for the numeric
 * matchup blend in weeklyProjection.ts. Null when the position has no data.
 */
export function leagueAvgAllowed(position: string | null | undefined): number | null {
  const pos = normalizePosition(position);
  if (pos === null) return null;
  const avgs = Object.values(ALLOWED.teams)
    .map(team => team[pos]?.avg)
    .filter((a): a is number => Number.isFinite(a));
  if (avgs.length === 0) return null;
  return Math.round((avgs.reduce((s, a) => s + a, 0) / avgs.length) * 100) / 100;
}
